function homeAudienceBuildSituation(kind,seed={}){
 const places=homeAudienceSettlementPool(),origin=seed.originId?places.find(x=>x.id===seed.originId):pick(places),otherPool=places.filter(x=>!origin||x.id!==origin.id),subject=seed.subjectId?places.find(x=>x.id===seed.subjectId):pick(otherPool.length?otherPool:places);
 const originId=origin?.id||'shantium',subjectId=subject?.id||'shantium',originName=homeAudiencePlace(originId),subjectName=homeAudiencePlace(subjectId),faction=seed.faction||homeAudienceFactionName(subjectId)||homeAudienceFactionName(originId),good=seed.goodId&&typeof worldGood==='function'?worldGood(seed.goodId):homeAudienceGoodForRoute(originId,subjectId),goodName=good?.name||'supplies';
 const guards=faction?`${faction} patrols`:'road patrols',days=rnd(2,9),wagons=rnd(2,6),families=rnd(3,12);
 let x={originId,subjectId,goodId:good?.id||null,faction:faction||null,origin:originName,purpose:'They have come to speak with the Guardian personally.',text:'They ask for a private audience.',hook:'The visitor waits until the door is shut before getting to the point.',detail:'They give the Guardian the facts as they know them.',counsel:'You give a short answer and send them on their way.'};
 if(kind==='resident')Object.assign(x,{originId:'shantium',origin:'Shantium',purpose:`A Shantium resident wants help with a dispute over carts and deliveries near the ${pick(['south gate','market quarter','river road','old wall'])}.`,text:`For ${days} days, wagons have been blocking the street before sunrise. The resident says watchmen have moved them twice, but they return the next morning.`,hook:`The resident has brought a rough list of wagon marks and the names of two shopkeepers who can confirm the complaint.`,detail:`The trouble starts before dawn. Two wagons arrive first, then another three or four. The drivers unload ${goodName.toLowerCase()} and leave the carts in the street until midday. The resident says nobody has asked for money; they simply want the road kept open.`,counsel:`You tell them to give the list to the Steward and to come back if the watch ignores the same wagons again.`});
 if(kind==='merchant')Object.assign(x,{purpose:`A merchant from ${originName} wants to talk about moving ${goodName.toLowerCase()} toward ${subjectName}.`,text:`The merchant says the last run took ${days} days longer than expected after repeated stops on the road.`,hook:`The merchant puts a folded route sheet on the table and points to the stretch nearest ${subjectName}.`,detail:`The caravan carried ${goodName.toLowerCase()} from ${originName}. Near ${subjectName}, ${guards} stopped the lead wagons and searched the cargo. Nothing was taken, but the caravan lost most of a day and two hired guards quit before the return trip.`,counsel:`You advise the merchant to keep the next caravan together, record the names or badges of any patrol that stops it, and send word to the Hall if the searches happen again.`});
 if(kind==='artisan')Object.assign(x,{originId:'shantium',origin:'Shantium',purpose:`A Shantium craftsperson is having trouble getting enough ${goodName.toLowerCase()} for regular work.`,text:`Their usual seller now sends most of the available stock elsewhere, and prices in Shantium have risen sharply.`,hook:`The artisan sets a worn sample on the table and says the problem is not workmanship—it's getting the right material at all.`,detail:`The last shipment from ${originName==='Shantium'?subjectName:originName} was barely half the usual size. The artisan has enough ${goodName.toLowerCase()} for current orders, but not for the next batch due at the end of the week.`,counsel:`You suggest they bring the Steward the supplier's name and current price before asking the Hall to intervene.`});
 if(kind==='stranger')Object.assign(x,{purpose:`A road traveler from ${originName} asks to report something seen on the way toward ${subjectName}.`,text:`They do not know whether what they saw was criminal, political, or simply strange, but it bothered them enough to stop at the Hall.`,hook:`The traveler keeps glancing toward the door and starts by saying exactly where they were when it happened.`,detail:`About a mile outside ${subjectName}, they saw ${rnd(4,9)} armed riders leave the main road and cut across open ground. One horse carried ${faction?`${faction} colors`:'a red cloth beneath the saddle'}, but the traveler saw no clear insignia.`,counsel:`You tell the traveler not to chase rumors. If they see the riders again, they should note direction, numbers, and markings and report it to the nearest watch post.`});
 if(kind==='veteran')Object.assign(x,{purpose:`A veteran from ${originName} wants to talk about former soldiers taking guard work on the ${subjectName} road.`,text:`Several veterans have been hired cheaply by caravans and dismissed after dangerous runs without full pay.`,hook:`The veteran names two men they served with and says both came home from the ${subjectName} road without the wages they were promised.`,detail:`One company offered twelve days of guard pay for a run carrying ${goodName.toLowerCase()}. The caravan returned after seventeen days. The guards were paid for twelve and told the delay was their own problem.`,counsel:`You tell the veteran to bring the contracts and the names of the caravan owners. A complaint backed by names and paper will carry more weight than tavern talk.`});
 if(kind==='scholar')Object.assign(x,{purpose:`A scholar from ${originName} is trying to verify an old account involving ${subjectName}${faction?` and ${faction}`:''}.`,text:`Two surviving accounts disagree over who controlled the road and who ordered a disputed seizure.`,hook:`The scholar opens two copied passages side by side. The dates match; almost nothing else does.`,detail:`One account says ${faction||'local troops'} stopped a convoy outside ${subjectName}. The other says the convoy turned back voluntarily. The scholar wants to know whether Guardian Hall has letters, ledgers, or eyewitness testimony from the same season.`,counsel:`You give only what you actually remember and tell the scholar not to put the Guardian's name behind anything the Hall cannot prove.`});
 if(kind==='healer')Object.assign(x,{purpose:`A healer from ${originName} is short of ${goodName.toLowerCase()} and worries ${subjectName} may be next.`,text:`Two expected deliveries have failed to arrive, and the healer has begun rationing what remains.`,hook:`The healer has brought an empty case and a written list of what is left at the clinic.`,detail:`The first shipment should have arrived ${days} days ago. A second was due two days later. Neither reached ${originName}. The healer has enough stock for ordinary cases, but not for a serious accident or outbreak.`,counsel:`You tell the healer to leave a copy of the list with the Steward and reserve the remaining stock for urgent cases until the missing shipments are traced.`});
 if(kind==='courier')Object.assign(x,{purpose:`A courier out of ${originName} delivered a message from ${subjectName}, but the trip itself is what worries them.`,text:`Someone followed the courier for part of the road and disappeared before the last checkpoint.`,hook:`The courier places the sealed delivery on the table, then says, “That part is ordinary. The road wasn't.”`,detail:`A lone rider picked up the courier outside ${subjectName} and stayed behind them for nearly half a day. The rider never approached. At the next patrol stop, the rider turned off the road and vanished.`,counsel:`You advise the courier to change the return route if possible and to tell the Steward immediately if the same rider appears near the Hall.`});
 if(kind==='caravan_master')Object.assign(x,{purpose:`A caravan master from ${originName} wants to discuss the ${subjectName} run and a cargo of ${goodName.toLowerCase()}.`,text:`The latest caravan reached Shantium intact, but the master says the route is becoming harder to price and protect.`,hook:`The caravan master spreads a stained route sheet across the table and taps two marks beside ${subjectName}.`,detail:`The caravan had ${wagons} wagons of ${goodName.toLowerCase()}. ${guards} stopped it twice near ${subjectName}. No cargo was seized, but each stop cost hours, feed, and guard wages. The master says another delay like that will wipe out the profit on the run.`,counsel:`You tell the master to keep a written record of each stop and not to pay unofficial “road fees” without names, colors, or witnesses.`});
 if(kind==='civic_delegate')Object.assign(x,{originId:'shantium',origin:'Shantium',purpose:`A small Shantium delegation wants the Guardian to hear a neighborhood dispute involving traders from ${subjectName}.`,text:`Shopkeepers and residents disagree over where visiting wagons should unload, and the arguments have begun drawing the watch.`,hook:`The delegates are polite until one mentions the unloading yard; then three of them start talking at once.`,detail:`Traders from ${subjectName} have been unloading ${goodName.toLowerCase()} beside a residential lane because the usual yard fills early. Residents say doors are blocked and animals foul the street. The traders say the legal yard charges more than they can afford.`,counsel:`You tell the delegates to bring the Steward the yard fees and the names of the affected traders. The Hall will not settle a street quarrel on hearsay.`});
 if(kind==='grateful_family')Object.assign(x,{purpose:`A family from ${originName} has come to thank the Guardian for help that reached them on the road to ${subjectName}.`,text:`They say a Hall-backed patrol or relief action got them home when they had run out of money and food.`,hook:`They have no petition. The eldest member of the family simply asks to tell you what happened after the Hall's help arrived.`,detail:`There were ${families} people traveling together when their cart broke near ${subjectName}. They expected to abandon most of their belongings. Help reached them before nightfall, and every member of the family made it back to ${originName}.`,counsel:`You ask after the family, accept their thanks, and tell them to spend their money on getting settled rather than bringing gifts to the Hall.`});
 if(kind==='witness')Object.assign(x,{purpose:`A witness from ${originName} wants to report armed movement near ${subjectName}.`,text:`They are frightened enough to insist on speaking somewhere private.`,hook:`The witness waits for the doors to close before saying they saw armed riders leave the road after dark.`,detail:`They counted ${rnd(5,10)} riders outside ${subjectName}. The group carried no torches and avoided the checkpoint. The witness thought one rider wore ${faction?`${faction} colors`:'a faction-colored sash'}, but it was too dark to be certain.`,counsel:`You tell the witness exactly what to repeat to the watch: number of riders, direction, time, and only the markings they are certain they saw.`});
 if(kind==='known_group')Object.assign(x,{purpose:`${seed.name||'A known traveling group'} has returned from ${originName} with news from the ${subjectName} road.`,text:`They want to trade news before moving on again.`,hook:`There is little ceremony. Once seated, they start with the road and who they met on it.`,detail:`The group passed ${subjectName} ${days} days ago. They saw a caravan carrying ${goodName.toLowerCase()} under heavier guard than usual and heard that merchants expect more stops ahead.`,counsel:`You trade what you know and ask them to send word if the ${subjectName} road changes before their next visit.`});
 if(kind==='known_contact')Object.assign(x,{purpose:`${seed.name||'A known contact'} has returned from ${originName} and wants a private word about ${subjectName}.`,text:`They have heard something they would rather tell the Guardian directly.`,hook:`Because you already know one another, they skip the formal greeting and get straight to the news.`,detail:`They heard that ${faction||'local authorities'} have been asking unusually specific questions about travelers coming through ${subjectName}. They cannot say why, only that your name was mentioned once.`,counsel:`You thank them for bringing it directly and ask them not to press for answers on your behalf.`});
 if(kind==='former_prisoner')Object.assign(x,{purpose:`A former prisoner from ${originName} brings a warning about travelers headed toward ${subjectName}.`,text:`They recognized a face from their captivity while on the road and kept enough distance to avoid being noticed.`,hook:`They are calm until they name the person they recognized. Then their hands start to shake.`,detail:`Near ${originName}, the former prisoner saw someone they recognized from captivity traveling toward ${subjectName} with two companions. None of the three showed visible faction colors. The former prisoner continued on to Shantium and brought the description to the Hall.`,counsel:`You tell them they were right to avoid a confrontation and ask the Steward to pass the description and reported route to security.`});
 if(seed.returning){x.hook=`${seed.name||'The visitor'} is recognized at once. After a brief greeting, they say the matter that brought them back concerns ${subjectName}.`;x.purpose=`${seed.name||'A returning visitor'} has come back to the Hall with new information from ${originName}.`}
 return x
}
